('anatomy', 'Special Senses', 'What structure separates the outer ear from the middle ear?', 'mcq', '["Cochlea", "Stapes", "Tympanic membrane", "Semicircular canal"]'::jsonb, 'Tympanic membrane', 'The tympanic membrane, or eardrum, vibrates in response to sound.', 'easy', 'NursaFlow-Custom', 'ap-291', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'Which small bone is commonly called the stirrup?', 'mcq', '["Cochlea", "Stapes", "Incus", "Malleus"]'::jsonb, 'Stapes', 'The stapes is the smallest of the three auditory ossicles and is shaped like a stirrup.', 'easy', 'NursaFlow-Custom', 'ap-292', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'Which small bone is commonly called the hammer?', 'mcq', '["Incus", "Malleus", "Cochlea", "Stapes"]'::jsonb, 'Malleus', 'The malleus is the hammer-shaped auditory ossicle.', 'easy', 'NursaFlow-Custom', 'ap-293', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'Which small bone is commonly called the anvil?', 'mcq', '["Malleus", "Stapes", "Incus", "Pinna"]'::jsonb, 'Incus', 'The incus is the anvil-shaped auditory ossicle.', 'easy', 'NursaFlow-Custom', 'ap-294', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'Which cranial nerve carries smell information?', 'mcq', '["Vagus nerve", "Trigeminal nerve", "Optic nerve", "Olfactory nerve"]'::jsonb, 'Olfactory nerve', 'The olfactory nerve carries sensory information related to smell.', 'easy', 'NursaFlow-Custom', 'ap-295', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'Which cranial nerve is responsible for much of the sense of taste from the anterior two-thirds of the tongue?', 'mcq', '["Facial nerve", "Olfactory nerve", "Accessory nerve", "Optic nerve"]'::jsonb, 'Facial nerve', 'The facial nerve carries taste sensation from the anterior two-thirds of the tongue via the chorda tympani.', 'easy', 'NursaFlow-Custom', 'ap-296', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'Which structure contains taste buds?', 'mcq', '["Papillae of the tongue", "Osteons", "Alveoli", "Nephrons"]'::jsonb, 'Papillae of the tongue', 'Many taste buds are located in papillae on the tongue.', 'easy', 'NursaFlow-Custom', 'ap-297', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'What is the transparent front surface of the eye called?', 'mcq', '["Sclera", "Retina", "Cornea", "Iris"]'::jsonb, 'Cornea', 'The cornea is the transparent anterior surface and contributes significantly to light refraction.', 'easy', 'NursaFlow-Custom', 'ap-298', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'What is the white outer layer of the eye called?', 'mcq', '["Retina", "Sclera", "Choroid", "Cornea"]'::jsonb, 'Sclera', 'The sclera is the tough white outer coat of most of the eyeball.', 'easy', 'NursaFlow-Custom', 'ap-299', 'Proprietary (author-supplied, pending confirmation)', false, 'review'),
('anatomy', 'Special Senses', 'What is the central area of the retina responsible for sharpest vision called?', 'mcq', '["Ciliary body", "Sclera", "Fovea centralis", "Optic disc"]'::jsonb, 'Fovea centralis', 'The fovea centralis has a high density of cones and provides the sharpest central vision.', 'easy', 'NursaFlow-Custom', 'ap-300', 'Proprietary (author-supplied, pending confirmation)', false, 'review')
